/* Yaad Saathi — flat, dependency-free GitHub Pages PWA */
(() => {
  'use strict';
  const DB='yaad-saathi-v3', STORE='state', KEY='state';
  const app=document.getElementById('app'), toastEl=document.getElementById('toast');
  const nowISO=()=>new Date().toISOString();
  const uid=()=>crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
  const today=()=>{const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)};
  const empty=()=>({profile:{name:'',photo:''},theme:'soft',lang:'en',notifications:false,installDismissed:false,items:[],notebook:[],reminders:[],vault:{salt:'',data:''},streak:{last:'',count:0},customCats:[]});
  let state=empty(), route='home', filter='all', deferredInstall=null, installTimer=null, reminderTimers=[];
  const cats={
    things:{label:'My Things',ur:'میری چیزیں',icon:'box',hint:'Items you own and want to remember'},
    buyAgain:{label:'Buy Again',ur:'پھر سے لینا ہے',icon:'refresh',hint:'Things you buy repeatedly'},
    memory:{label:'Memory Notes',ur:'میموری نوٹس',icon:'spark',hint:'Short personal memories'},
    reminders:{label:'Reminders',ur:'یاد دہانیاں',icon:'bell',hint:'Dates, tasks and alarms'},
    documents:{label:'Documents',ur:'دستاویزات',icon:'file',hint:'Personal documents and files'},
    warranty:{label:'Warranty & Bills',ur:'وارنٹی اور بل',icon:'receipt',hint:'Warranties, bills and receipts'},
    wishlist:{label:'Gifts & Wishlist',ur:'گفٹس اور خواہشات',icon:'gift',hint:'Things to buy for yourself or others'},
    futureMe:{label:'Future Me',ur:'کل کا میں',icon:'clock',hint:'Write a message for your future self'},
    vault:{label:'Secure Vault',ur:'محفوظ والٹ',icon:'lock',hint:'Private account details and passwords'}
  };
  const iconPaths={
    menu:'<path d="M4 7h16M4 12h16M4 17h16"/>', search:'<circle cx="11" cy="11" r="6.5"/><path d="m16 16 4 4"/>', user:'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c.8-4 3-6 7-6s6.2 2 7 6"/>', home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/>', bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>', settings:'<path d="M12 8.5a3.5 3.5 0 1 0 0 7 3.5 3.5 0 0 0 0-7Z"/><path d="M4.9 15.1 3.5 16l1.7 2.9 1.6-.8a8.4 8.4 0 0 0 2.4 1.4V21h3.4v-1.5a8.4 8.4 0 0 0 2.4-1.4l1.6.8 1.7-2.9-1.4-.9a8.1 8.1 0 0 0 0-2.2l1.4-.9-1.7-2.9-1.6.8a8.4 8.4 0 0 0-2.4-1.4V7H9.2v1.5a8.4 8.4 0 0 0-2.4 1.4l-1.6-.8-1.7 2.9 1.4.9a8.1 8.1 0 0 0 0 2.2Z"/>', plus:'<path d="M12 5v14M5 12h14"/>', x:'<path d="m6 6 12 12M18 6 6 18"/>', chev:'<path d="m9 18 6-6-6-6"/>', box:'<path d="m12 3 8 4.5v9L12 21l-8-4.5v-9z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>', refresh:'<path d="M20 7v5h-5"/><path d="M4 17v-5h5"/><path d="M6.1 9a7 7 0 0 1 11.8-2L20 8M4 16l2.1 1A7 7 0 0 0 17.9 15"/>', notebook:'<path d="M6 4h12a2 2 0 0 1 2 2v13H8a2 2 0 0 1-2-2z"/><path d="M6 7H4v11a2 2 0 0 0 2 2M10 9h7M10 13h7"/>', spark:'<path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5z"/><path d="m19 16 .7 2.3L22 19l-2.3.7L19 22l-.7-2.3L16 19l2.3-.7z"/>', file:'<path d="M6 3h8l4 4v14H6z"/><path d="M14 3v5h5M9 13h6M9 17h6"/>', receipt:'<path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h3"/>', gift:'<path d="M4 10h16v11H4zM2 7h20v3H2zM12 7v14M12 7H8.5a2.5 2.5 0 1 1 2.5-2.5V7Zm0 0h3.5a2.5 2.5 0 1 0-2.5-2.5V7Z"/>', mic:'<rect x="8" y="3" width="8" height="12" rx="4"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3M9 21h6"/>', camera:'<path d="M4 7h4l1.5-2h5L16 7h4v12H4z"/><circle cx="12" cy="13" r="3.5"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', trash:'<path d="M4 7h16M10 11v6M14 11v6M6 7l1 14h10l1-14M9 7V4h6v3"/>', edit:'<path d="m4 20 4-.8L19 8.2a2.1 2.1 0 0 0-3-3L5 16.2z"/><path d="m14.5 6.5 3 3"/>', download:'<path d="M12 3v11M8 10l4 4 4-4M4 20h16"/>', upload:'<path d="M12 21V10M8 14l4-4 4 4M4 4h16"/>', share:'<path d="M14 5h5v5M19 5l-9 9"/><path d="M19 13v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h5"/>', shield:'<path d="M12 3 20 6v6c0 5-3.2 8.3-8 9-4.8-.7-8-4-8-9V6z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>', unlock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 7-2"/>', filter:'<path d="M4 6h16M7 12h10M10 18h4"/>', check:'<path d="m5 12 4 4L19 6"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 10v6M12 7h.01"/>', play:'<path d="m8 5 11 7-11 7z"/>', stop:'<rect x="7" y="7" width="10" height="10" rx="2"/>', eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/>', eyeoff:'<path d="m3 3 18 18M10.6 10.6a2 2 0 0 0 2.8 2.8"/><path d="M9.9 5.2A10.7 10.7 0 0 1 12 5c6.5 0 10 7 10 7a18 18 0 0 1-3.1 3.9M6.5 6.6C3.7 8.3 2 12 2 12s3.5 7 10 7c1 0 1.9-.2 2.7-.5"/>', calendar:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>', wallet:'<path d="M4 6h15a1 1 0 0 1 1 1v12H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-1Z"/><path d="M20 10h-6a2 2 0 0 0 0 4h6M16 12h.01"/>', archive:'<path d="M4 5h16v4H4zM6 9v11h12V9M9 13h6"/>', help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.7 2.7 0 1 1 4.7 1.8c-.9 1-2.2 1.4-2.2 3M12 17h.01"/>', copy:'<rect x="8" y="8" width="11" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h2"/>'
  };
  const I=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[n]||iconPaths.spark}</svg>`;
  const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const fmtDate=d=>d?new Intl.DateTimeFormat(state.lang==='ur'?'ur-PK':'en-PK',{day:'numeric',month:'short',year:'numeric'}).format(new Date(d+'T00:00:00')):'';
  const fmtTime=t=>t?new Intl.DateTimeFormat(state.lang==='ur'?'ur-PK':'en-PK',{hour:'numeric',minute:'2-digit'}).format(new Date('2000-01-01T'+t)):'';
  const t=(en,ur)=>state.lang==='ur'?ur:en;
  const catLabel=k=>state.lang==='ur'?cats[k]?.ur||cats[k]?.label||k:cats[k]?.label||k;
  const count=k=>state.items.filter(x=>x.category===k).length;
  const save=async()=>{await dbPut(state);scheduleReminders();};
  function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
  async function dbGet(){try{const db=await openDB();return await new Promise((res,rej)=>{const q=db.transaction(STORE,'readonly').objectStore(STORE).get(KEY);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}catch{return null}}
  async function dbPut(v){try{const db=await openDB();return await new Promise((res,rej)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(v,KEY);tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}catch{localStorage.setItem(DB,JSON.stringify(v))}}
  function normalize(){const base=empty();state={...base,...state,profile:{...base.profile,...(state.profile||{})},vault:{...base.vault,...(state.vault||{})},streak:{...base.streak,...(state.streak||{})},items:Array.isArray(state.items)?state.items.map(x=>x.category==='voice'?{...x,category:'memory'}:x):[],notebook:Array.isArray(state.notebook)?state.notebook:[],reminders:Array.isArray(state.reminders)?state.reminders:[],customCats:Array.isArray(state.customCats)?state.customCats.slice(0,2):[]};syncCustomCats()}
  function syncCustomCats(){Object.keys(cats).filter(k=>k.startsWith('custom')).forEach(k=>delete cats[k]);(state.customCats||[]).slice(0,2).forEach((c,i)=>{const key='custom'+(i+1);cats[key]={label:c.label||('Custom '+(i+1)),ur:c.ur||c.label||('کسٹم '+(i+1)),icon:'spark',hint:'Your own custom category'}})}
  function applyTheme(){document.documentElement.classList.toggle('dark',state.theme==='dark');document.documentElement.dataset.theme=state.theme;document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ur'?'rtl':'ltr'}
  function greeting(){const h=new Date().getHours();return h<12?t('GOOD MORNING,','صبح بخیر،'):h<18?t('GOOD AFTERNOON,','دوپہر بخیر،'):t('GOOD EVENING,','شام بخیر،')}
  function dateText(){return new Intl.DateTimeFormat(state.lang==='ur'?'ur-PK':'en-PK',{weekday:'long',month:'long',day:'numeric'}).format(new Date())}
  function allRecords(){return state.items}
  function recent(){return [...allRecords()].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,5)}
  function dueToday(){return state.reminders.filter(r=>!r.completed&&r.date===today()).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'))}
  function futureToday(){return state.items.filter(x=>x.category==='futureMe'&&!x.sent&&x.date===today()).sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'))}
  function streakText(){const s=state.streak;return s.count?t(`${s.count}-day memory streak`,`آپ کی ${s.count} دن کی میموری اسٹریك`):t('Start your memory streak today','آج اپنی میموری اسٹریك شروع کریں')}
  function touchStreak(){const d=today();if(state.streak.last===d)return;if(state.streak.last){const diff=Math.round((new Date(d)-new Date(state.streak.last))/86400000);state.streak.count=diff===1?state.streak.count+1:1}else state.streak.count=1;state.streak.last=d}
  function layout(content){app.innerHTML=`<div class="app-shell"><main class="app-main">${topbar()}${content}</main>${bottomNav()}${installBanner()}</div>`;bindCommon()}
  function topbar(){return `<header class="topbar"><div class="brand"><button class="icon-btn" data-action="menu" aria-label="Menu">${I('menu')}</button><div class="brand-mark" aria-hidden="true"><span class="brand-logo-art"><i></i><b></b><em></em></span></div><div><div class="brand-name">YAAD SAATHI</div><div class="brand-sub">یاد ساتھی</div></div></div><div class="top-actions"><button class="icon-btn" data-action="search" aria-label="Search">${I('search')}</button><button class="icon-btn" data-action="profile" aria-label="Profile">${state.profile.photo?`<img src="${esc(state.profile.photo)}" style="width:100%;height:100%;object-fit:cover;border-radius:15px">`:I('user')}</button></div></header>`}
  function bottomNav(){const active=x=>route===x?' active':'';return `<nav class="bottom-nav"><button class="nav-btn${active('home')}" data-route="home">${I('home')}<span>${t('Home','ہوم')}</span></button><button class="nav-btn${active('search')}" data-route="search">${I('search')}<span>${t('Search','تلاش')}</span></button><div class="nav-add"><button data-action="add" aria-label="Add">${I('plus')}</button></div><button class="nav-btn${active('reminders')}" data-route="reminders">${I('bell')}<span>${t('Reminders','یاد دہانیاں')}</span></button><button class="nav-btn${active('settings')}" data-route="settings">${I('settings')}<span>${t('Settings','سیٹنگز')}</span></button></nav>`}
  function splash(){return ''}
  function installBanner(){return `<div id="install-banner" class="install-card hidden"><div class="install-icon">${I('download')}</div><div class="install-copy"><strong>${t('Install Yaad Saathi','یاد ساتھی انسٹال کریں')}</strong><span>${t('Keep it one tap away on this device.','اسے اس ڈیوائس پر ایک ٹیپ کی دوری پر رکھیں۔')}</span></div><div class="install-actions"><button class="install-go" data-action="install">${t('Install','انسٹال')}</button><button class="install-close" data-action="dismiss-install">${I('x')}</button></div></div>`}
  function home(){const due=dueToday();const quick=['things','buyAgain','memory','documents','futureMe',...(state.customCats||[]).map((_,i)=>'custom'+(i+1))].slice(0,6);const rec=recent();return `<section class="hero"><div class="eyebrow">${greeting()}</div><h1>${t('What needs remembering today?','آج کیا یاد رکھنا ہے؟')}</h1><div class="hero-date">${esc(dateText())}</div>${state.lang==='ur'?'<div class="hero-urdu">آپ کی ضروری چیزیں، یادیں اور کام ایک جگہ۔</div>':''}</section>
  <section class="today-card glass botanical-card"><div class="card-head"><div class="head-left"><div class="mini-icon">${I('spark')}</div><div class="section-title">${t('Today','آج')}</div></div><div class="pill">${due.length} ${t('coming up','آنے والے')}</div></div>${due.length?due.slice(0,2).map(r=>`<button class="today-item" data-action="open-reminder" data-id="${r.id}" style="border:0;background:transparent;width:100%;text-align:left;color:inherit"><div class="item-icon">${I(r.kind==='bill'?'receipt':'bell')}</div><div class="item-main"><div class="item-title">${esc(r.title)}</div><div class="item-meta">${fmtTime(r.time)||t('Today','آج')} ${r.amount?`· ${esc(r.amount)}`:''}</div></div><div class="chev">${I('chev')}</div></button>`).join(''):`<div class="empty" style="margin-top:15px;padding:22px"><div class="empty-icon">${I('check')}</div><h3>${t('A clear day','آج سب صاف ہے')}</h3><p>${t('Nothing urgent is waiting. Add a reminder when you need one.','فی الحال کوئی ضروری کام نہیں۔ جب چاہیں نئی یاد دہانی شامل کریں۔')}</p></div>`}</section>${futureToday().length?`<section class="future-today glass"><div class="future-today-icon">${I('clock')}</div><div><div class="section-label">${t('Future Me — today','کل کا میں — آج')}</div><h3>${esc(futureToday()[0].title)}</h3><p>${esc(futureToday()[0].note||t('A message from you, for you.','آپ کا اپنے لیے پیغام۔'))}</p></div></section>`:''}
  <section class="section"><div class="section-bar"><div><div class="section-label">${t('Quick Add','فوری اضافہ')}</div><h2>${t('Today','آج')}</h2></div><button class="text-btn" data-action="see-all">${t('See all','سب دیکھیں')} ${I('chev')}</button></div><div class="quick-row">${quick.map(k=>`<button class="quick-card" data-category="${k}"><span class="count">${count(k)}</span><span class="qicon">${I(cats[k].icon)}</span><strong>${catLabel(k)}</strong><span>${esc(cats[k].hint)}</span></button>`).join('')}</div></section>
  <section class="capture"><div class="capture-content"><div class="capture-icon">${I('camera')}</div><h3>${t('Smart Capture','اسمارٹ کیپچر')}</h3><p>${t('Save a photo or quick memory, then choose where it belongs.','تصویر یا فوری یاد محفوظ کریں، پھر منتخب کریں کہ اسے کہاں رکھنا ہے۔')}</p><div class="capture-actions"><button class="light-btn" data-action="capture-photo">${I('camera')} ${t('Photo','تصویر')}</button><button class="light-btn" data-action="capture-note">${I('notebook')} ${t('Quick note','فوری نوٹ')}</button></div></div></section>
  <section class="section"><div class="section-bar"><div><div class="section-label">${t('Memory Pulse','میموری پلس')}</div><h2>${streakText()}</h2></div></div><div class="stats"><div class="stat glass"><b>${state.items.length}</b><span>${t('Saved items','محفوظ چیزیں')}</span></div><div class="stat glass"><b>${state.reminders.filter(r=>!r.completed).length}</b><span>${t('Open reminders','کھلی یاد دہانیاں')}</span></div><div class="stat glass"><b>${count('documents')}</b><span>${t('Documents','دستاویزات')}</span></div></div></section>
  <section class="section"><div class="section-bar"><div><div class="section-label">${t('Recently added','حال ہی میں')}</div><h2>${t('Your history','آپ کی ہسٹری')}</h2></div></div>${rec.length?`<div class="recent-list">${rec.map(recordRow).join('')}</div>`:`<div class="empty"><div class="empty-icon">${I('spark')}</div><h3>${t('Your memory history starts here','آپ کی میموری ہسٹری یہاں سے شروع ہوگی')}</h3><p>${t('Anything you save will appear here so old entries never disappear.','آپ جو بھی محفوظ کریں گے وہ یہاں نظر آئے گا، پرانی چیزیں غائب نہیں ہوں گی۔')}</p></div>`}</section>`}
  function recordRow(x){return `<button class="recent-item" data-action="open-record" data-id="${x.id}" style="width:100%;border:1px solid var(--line);text-align:left;color:inherit"><div class="mini-icon">${I(cats[x.category]?.icon||'spark')}</div><div class="item-main"><div class="item-title">${esc(x.title)}</div><div class="item-meta">${catLabel(x.category)} · ${fmtDate(x.createdAt.slice(0,10))}</div></div><div class="chev">${I('chev')}</div></button>`}
  function searchPage(){const q=(window.__query||'').trim().toLowerCase();const records=state.items.filter(x=>{const hay=[x.title,x.note,x.body,x.category,x.tags?.join(' ')].filter(Boolean).join(' ').toLowerCase();return !q||hay.includes(q)}).filter(x=>filter==='all'||x.category===filter);return `<div class="page-title"><div class="eyebrow">${t('YOUR MEMORY','آپ کی میموری')}</div><h1>${t('Search','تلاش')}</h1></div><div class="search-box">${I('search')}<input id="global-search" value="${esc(window.__query||'')}" placeholder="${t('Search everything…','سب کچھ تلاش کریں…')}" autofocus></div><div class="filter-row"><button class="filter ${filter==='all'?'active':''}" data-filter="all">${t('All','سب')}</button>${Object.keys(cats).filter(k=>k!=='vault').map(k=>`<button class="filter ${filter===k?'active':''}" data-filter="${k}">${catLabel(k)}</button>`).join('')}</div>${records.length?`<div class="list-grid">${records.map(r=>recordCard(r)).join('')}</div>`:`<div class="empty"><div class="empty-icon">${I('search')}</div><h3>${t('Nothing found','کچھ نہیں ملا')}</h3><p>${t('Try another word or add something new.','دوسرا لفظ آزمائیں یا نئی چیز شامل کریں۔')}</p></div>`}`}
  function recordCard(x){return `<article class="record"><div class="thumb">${x.photo?`<img src="${esc(x.photo)}" style="width:100%;height:100%;object-fit:cover;border-radius:17px">`:I(cats[x.category]?.icon||'spark')}</div><div class="record-body"><div class="item-title">${esc(x.title)}</div><div class="item-meta">${catLabel(x.category)}${x.note?` · ${esc(x.note)}`:''}</div><div class="item-meta">${fmtDate(x.createdAt.slice(0,10))}</div></div><div class="record-actions"><button class="small-btn" data-action="edit-record" data-id="${x.id}">${I('edit')}</button><button class="small-btn danger" data-action="delete-record" data-id="${x.id}">${I('trash')}</button></div></article>`}
  function remindersPage(){const list=[...state.reminders].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<div class="page-title"><div class="eyebrow">${t('YOUR DAY','آپ کا دن')}</div><h1>${t('Reminders','یاد دہانیاں')}</h1></div><div class="list-grid">${list.length?list.map(r=>`<article class="record"><button class="small-btn" data-action="toggle-reminder" data-id="${r.id}" style="margin-top:2px">${I(r.completed?'check':'bell')}</button><div class="record-body"><div class="item-title" style="${r.completed?'text-decoration:line-through;opacity:.55':''}">${esc(r.title)}</div><div class="item-meta">${fmtDate(r.date)}${r.time?' · '+fmtTime(r.time):''}${r.recurrence&&r.recurrence!=='none'?' · '+r.recurrence:''}</div>${r.note?`<div class="item-meta">${esc(r.note)}</div>`:''}</div><div class="record-actions"><button class="small-btn" data-action="edit-reminder" data-id="${r.id}">${I('edit')}</button><button class="small-btn danger" data-action="delete-reminder" data-id="${r.id}">${I('trash')}</button></div></article>`).join(''):`<div class="empty"><div class="empty-icon">${I('bell')}</div><h3>${t('No reminders yet','ابھی کوئی یاد دہانی نہیں')}</h3><p>${t('Add a date and time and Yaad Saathi will keep it visible here.','تاریخ اور وقت شامل کریں اور یاد ساتھی اسے یہاں نمایاں رکھے گا۔')}</p></div>`}</div>`}
  function settingsPage(){return `<div class="settings-head"><div class="about-card glass"><div><div class="eyebrow">${t('SETTINGS','سیٹنگز')}</div><h2>${t('About Yaad Saathi','یاد ساتھی کے بارے میں')}</h2><p>${t('A calm, private space for the things, notes, memories, documents and reminders you want to keep close.','آپ کی چیزوں، نوٹس، یادوں، دستاویزات اور یاد دہانیوں کے لیے ایک پرسکون اور نجی جگہ۔')}</p></div><div class="mini-icon">${I('shield')}</div></div></div>
  <section class="settings-section"><div class="setting-label">${I('spark')} ${t('Appearance','ظاہری انداز')}</div><div class="settings-card glass"><div class="theme-options">${[['soft','Botanical Glass','قدرتی گلاس'],['clear','Pearl Aurora','موتی جیسی روشنی'],['dark','Midnight Garden','رات کا باغ']].map(a=>`<button class="theme-opt ${state.theme===a[0]?'active':''}" data-theme="${a[0]}"><div class="theme-swatch ${a[0]==='clear'?'clear':a[0]==='dark'?'dark':''}"></div><b>${state.lang==='ur'?a[2]:a[1]}</b></button>`).join('')}</div></div></section>
  <section class="settings-section"><div class="setting-label">${I('spark')} ${t('Language','زبان')}</div><div class="settings-card glass"><div class="lang-row"><button class="lang-btn ${state.lang==='en'?'active':''}" data-lang="en">English</button><button class="lang-btn ${state.lang==='ur'?'active':''}" data-lang="ur">اردو</button></div></div></section>
  <section class="settings-section"><div class="setting-label">${I('bell')} ${t('Notifications','اطلاعات')}</div><div class="settings-card glass"><button class="setting-row" data-action="toggle-notifications"><div class="row-icon">${I('bell')}</div><div class="setting-copy"><strong>${t('Enable reminders on this device','اس ڈیوائس پر یاد دہانیاں فعال کریں')}</strong><span>${state.notifications?t('Notifications are enabled.','اطلاعات فعال ہیں۔'):t('Allow notifications to get reminder alerts when supported.','جہاں ممکن ہو یاد دہانی کے وقت اطلاع حاصل کریں۔')}</span></div><span class="pill">${state.notifications?t('ON','آن'):t('OFF','بند')}</span></button></div></section>
  <section class="settings-section"><div class="setting-label">${I('download')} ${t('Device & sharing','ڈیوائس اور شیئرنگ')}</div><div class="settings-card glass">${settingsRow('download',t('Install on this device','اس ڈیوائس پر انسٹال کریں'),t('Add Yaad Saathi to your home screen or desktop.','یاد ساتھی کو ہوم اسکرین یا ڈیسک ٹاپ پر شامل کریں۔'),'install')} ${settingsRow('share',t('Share Yaad Saathi link','یاد ساتھی کا لنک شیئر کریں'),t('Share this app without sharing your private data.','صرف ایپ کا لنک شیئر کریں، ذاتی ڈیٹا نہیں۔'),'share')} ${settingsRow('copy',t('Copy app link','ایپ لنک کاپی کریں'),t('Copy the current GitHub Pages address.','موجودہ GitHub Pages ایڈریس کاپی کریں۔'),'copy-link')}</div></section>
  <section class="settings-section"><div class="setting-label">${I('download')} ${t('Data management','ڈیٹا مینجمنٹ')}</div><div class="settings-card glass">${settingsRow('download',t('Export backup','بیک اپ ایکسپورٹ کریں'),t('Save your local data as a JSON backup.','اپنا مقامی ڈیٹا JSON بیک اپ کے طور پر محفوظ کریں۔'),'export')} ${settingsRow('upload',t('Import backup','بیک اپ امپورٹ کریں'),t('Restore a previously exported Yaad Saathi backup.','پہلے محفوظ کیا گیا بیک اپ واپس لائیں۔'),'import')} ${settingsRow('trash',t('Clear all app data','تمام ایپ ڈیٹا صاف کریں'),t('Permanently delete local memories, notes and reminders.','مقامی یادیں، نوٹس اور یاد دہانیاں مستقل حذف کریں۔'),'clear-data')}</div></section>
  <section class="settings-section"><div class="setting-label">${I('shield')} ${t('Privacy','پرائیویسی')}</div><div class="settings-card glass"><button class="setting-row" data-action="privacy-info"><div class="row-icon">${I('shield')}</div><div class="setting-copy"><strong>${t('Private by design','پرائیویسی کو ترجیح')}</strong><span>${t('Your normal data stays on this device. Secure Vault is encrypted with your passphrase.','عام ڈیٹا اسی ڈیوائس پر رہتا ہے۔ Secure Vault پاس فریز سے encrypted ہے۔')}</span></div>${I('chev')}</button></div></section>
  <section class="settings-section"><div class="setting-label">${I('spark')} ${t('Custom Categories','اپنی کیٹیگریز')}</div><div class="settings-card glass">${settingsRow('spark',t('Manage custom categories','اپنی کیٹیگریز بنائیں'),t('Create or rename up to two personal categories.','دو ذاتی کیٹیگریز بنائیں یا ان کے نام تبدیل کریں۔'),'custom-categories')}</div></section>
  <section class="settings-section"><div class="setting-label">${I('info')} ${t('About','تعارف')}</div><div class="settings-card glass"><div class="setting-row"><div class="row-icon">${I('spark')}</div><div class="setting-copy"><strong>${t('Developer by Muhammad Usman Channa','Developer by Muhammad Usman Channa')}</strong><span>Yaad Saathi · یاد ساتھی</span></div></div></div></section>`}
  function settingsRow(icon,title,sub,action){return `<button class="setting-row" data-action="${action}"><div class="row-icon">${I(icon)}</div><div class="setting-copy"><strong>${title}</strong><span>${sub}</span></div>${I('chev')}</button>`}
  function notebookPage(){const notes=[...state.notebook].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));return `<div class="page-title"><div class="eyebrow">${t('YOUR WRITING SPACE','آپ کی نوٹ بک')}</div><h1>${t('My Notebook','میری نوٹ بک')}</h1><button class="primary" data-action="new-notebook">${I('plus')} ${t('New note','نیا نوٹ')}</button></div>${notes.length?`<div class="list-grid">${notes.map(n=>`<article class="record"><div class="thumb">${I('notebook')}</div><div class="record-body"><div class="item-title">${esc(n.title||t('Untitled note','بغیر عنوان نوٹ'))}</div><div class="item-meta">${fmtDate(n.updatedAt.slice(0,10))}</div><div class="item-meta">${esc((n.body||'').slice(0,110))}</div></div><div class="record-actions"><button class="small-btn" data-action="edit-notebook" data-id="${n.id}">${I('edit')}</button><button class="small-btn danger" data-action="delete-notebook" data-id="${n.id}">${I('trash')}</button></div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-icon">${I('notebook')}</div><h3>${t('Your notebook is ready','آپ کی نوٹ بک تیار ہے')}</h3><p>${t('Write longer thoughts here. Short memories can stay in Memory Notes.','یہاں تفصیلی خیالات لکھیں۔ مختصر یادیں Memory Notes میں رکھیں۔')}</p></div>`}`}
  function allPage(){return `<div class="page-title"><div class="eyebrow">${t('ALL CATEGORIES','تمام کیٹیگریز')}</div><h1>${t('Your memory space','آپ کی میموری اسپیس')}</h1></div><div class="category-grid">${Object.keys(cats).filter(k=>k!=='vault').map(k=>`<button class="category-btn" data-category="${k}"><div class="qicon">${I(cats[k].icon)}</div><strong>${catLabel(k)}</strong><span>${esc(cats[k].hint)}</span></button>`).join('')}</div>`}
  function categoryPage(k){if(k==='vault')return '';const items=state.items.filter(x=>x.category===k).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return `<div class="page-title"><div class="eyebrow">${t('CATEGORY','کیٹیگری')}</div><h1>${catLabel(k)}</h1><button class="primary" data-action="add-category" data-category="${k}">${I('plus')} ${t('Add New','نیا شامل کریں')}</button></div>${items.length?`<div class="list-grid">${items.map(recordCard).join('')}</div>`:`<div class="empty"><div class="empty-icon">${I(cats[k].icon)}</div><h3>${t('Nothing saved here yet','ابھی یہاں کچھ محفوظ نہیں')}</h3><p>${t('Your old history will stay here after you add entries.','آپ جو کچھ پہلے محفوظ کریں گے وہ بھی اسی فہرست میں نظر آئے گا۔')}</p><button class="primary" data-action="add-category" data-category="${k}" style="max-width:260px">${t('Add the first one','پہلی چیز شامل کریں')}</button></div>`}`}
  function render(){syncCustomCats();applyTheme();let c='';if(route==='home')c=home();else if(route==='search')c=searchPage();else if(route==='reminders')c=remindersPage();else if(route==='settings')c=settingsPage();else if(route==='notebook')c=notebookPage();else if(route==='all')c=allPage();else if(route.startsWith('cat:'))c=categoryPage(route.slice(4));layout(c);if(route==='search')bindSearch();}
  function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>toastEl.classList.remove('show'),2400)}
  function openSheet(inner){const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="sheet"><div class="sheet-handle"></div>${inner}</div>`;b.addEventListener('click',e=>{if(e.target===b)b.remove()});document.body.appendChild(b);return b}
  function field(label,type,name,value='',placeholder='',extra=''){return `<div class="field"><label>${label}</label><input type="${type}" name="${name}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></div>`}
  function formCategory(k,id=''){const old=id?state.items.find(x=>x.id===id):null;const title=old?.title||'',note=old?.note||'',photo=old?.photo||'',future=k==='futureMe';return `<div class="sheet-title"><h2>${id?t('Edit item','آئٹم میں ترمیم'):catLabel(k)}</h2><button class="icon-btn" data-close>${I('x')}</button></div><form class="form" id="category-form">${field(t('Title','عنوان'),'text','title',title,t('What should you remember?','کیا یاد رکھنا ہے؟'),'required')} ${field(future?t('Send on','اس تاریخ پر دکھائیں'):t('Date','تاریخ'),'date','date',old?.date||today())}${future?field(t('Time','وقت'),'time','time',old?.time||'09:00'):''}<div class="field"><label>${t('Short note','مختصر نوٹ')}</label><textarea name="note" placeholder="${t('Add a little context…','تھوڑی سی تفصیل لکھیں…')}">${esc(note)}</textarea></div><div class="photo-picks"><label class="photo-picker">${I('camera')} ${t('Take photo','کیمرہ')}<input id="item-camera" type="file" accept="image/*" capture="environment" hidden></label><label class="photo-picker">${I('file')} ${t('Choose from gallery','گیلری')}<input id="item-gallery" type="file" accept="image/*" hidden></label></div><img id="photo-preview" class="photo-preview ${photo?'':'hidden'}" src="${photo?esc(photo):''}"><div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary" type="submit">${t('Save','محفوظ کریں')}</button></div></form>`}
  async function imageData(file,max=1800){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,img.width*scale);c.height=Math.max(1,img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.78))};img.onerror=rej;img.src=r.result};r.onerror=rej;r.readAsDataURL(file)})}
  function openCategory(k,id=''){const sh=openSheet(formCategory(k,id));sh.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>sh.remove()));let photo=id?state.items.find(x=>x.id===id)?.photo:'';const prev=sh.querySelector('#photo-preview');const useFile=async file=>{if(file){photo=await imageData(file);prev.src=photo;prev.classList.remove('hidden')}};sh.querySelector('#item-camera')?.addEventListener('change',e=>useFile(e.target.files[0]));sh.querySelector('#item-gallery')?.addEventListener('change',e=>useFile(e.target.files[0]));sh.querySelector('#category-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);const item={id:id||uid(),category:k,title:fd.get('title'),note:fd.get('note'),date:fd.get('date'),time:fd.get('time')||'',photo,createdAt:id?(state.items.find(x=>x.id===id)?.createdAt||nowISO()):nowISO(),updatedAt:nowISO(),audio:id?state.items.find(x=>x.id===id)?.audio:''};state.items=id?state.items.map(x=>x.id===id?{...x,...item}:x):[item,...state.items];touchStreak();await save();sh.remove();toast(t('Saved','محفوظ ہوگیا'));render()})}
  function openReminder(id=''){const old=id?state.reminders.find(x=>x.id===id):null;const sh=openSheet(`<div class="sheet-title"><h2>${id?t('Edit reminder','یاد دہانی میں ترمیم'):t('New reminder','نئی یاد دہانی')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><form class="form" id="rem-form">${field(t('Title','عنوان'),'text','title',old?.title||'',t('e.g. Internet bill','مثلاً انٹرنیٹ بل'),'required')}<div class="date-grid">${field(t('Start date','شروع ہونے کی تاریخ'),'date','date',old?.date||today())}${field(t('Start time / alarm','شروع وقت / الارم'),'time','time',old?.time||'09:00')}${field(t('End / expiry date','ختم ہونے کی تاریخ'),'date','endDate',old?.endDate||old?.date||today())}${field(t('End time','ختم ہونے کا وقت'),'time','endTime',old?.endTime||'23:59')}</div>${field(t('Amount (optional)','رقم (اختیاری)'),'text','amount',old?.amount||'','PKR 3,500')}<div class="field"><label>${t('Repeat','دہرائیں')}</label><select name="recurrence"><option value="none">${t('No repeat','نہیں')}</option><option value="monthly">${t('Monthly','ماہانہ')}</option><option value="yearly">${t('Yearly','سالانہ')}</option></select></div><div class="field"><label>${t('Note','نوٹ')}</label><textarea name="note">${esc(old?.note||'')}</textarea></div><div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Save reminder','یاد دہانی محفوظ کریں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',()=>sh.remove()));sh.querySelector('#rem-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);const r={id:id||uid(),title:fd.get('title'),date:fd.get('date'),time:fd.get('time'),endDate:fd.get('endDate'),endTime:fd.get('endTime'),amount:fd.get('amount'),recurrence:fd.get('recurrence'),note:fd.get('note'),completed:old?.completed||false,createdAt:old?.createdAt||nowISO()};state.reminders=id?state.reminders.map(x=>x.id===id?r:x):[r,...state.reminders];touchStreak();if(state.notifications&&'Notification' in window&&Notification.permission!=='granted')await Notification.requestPermission();await save();sh.remove();toast(t('Reminder saved','یاد دہانی محفوظ ہوگئی'));render()})}
  function openNotebook(id=''){const old=id?state.notebook.find(x=>x.id===id):null;const sh=openSheet(`<div class="sheet-title"><h2>${id?t('Edit note','نوٹ میں ترمیم'):t('New notebook note','نیا نوٹ')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><form class="form" id="note-form">${field(t('Title','عنوان'),'text','title',old?.title||'',t('Note title','نوٹ کا عنوان'))}<div class="field"><label>${t('Write','لکھیں')}</label><textarea name="body" style="min-height:240px" placeholder="${t('Write your thoughts here…','اپنے خیالات یہاں لکھیں…')}">${esc(old?.body||'')}</textarea></div><div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Save note','نوٹ محفوظ کریں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',()=>sh.remove()));sh.querySelector('#note-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target);const n={id:id||uid(),title:fd.get('title'),body:fd.get('body'),createdAt:old?.createdAt||nowISO(),updatedAt:nowISO()};state.notebook=id?state.notebook.map(x=>x.id===id?n:x):[n,...state.notebook];await save();sh.remove();toast(t('Notebook note saved','نوٹ محفوظ ہوگیا'));render()})}
  function openSmartCapture(kind='photo'){if(kind==='note')return openCategory('memory');const sh=openSheet(`<div class="sheet-title"><h2>${t('Smart Capture','اسمارٹ کیپچر')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="form"><div class="capture-choice-grid"><label class="capture-choice">${I('camera')}<strong>${t('Camera','کیمرہ')}</strong><span>${t('Take a new photo','نئی تصویر')}</span><input id="capture-camera" type="file" accept="image/*" capture="environment" hidden></label><label class="capture-choice">${I('file')}<strong>${t('Gallery','گیلری')}</strong><span>${t('Choose an existing photo','موجودہ تصویر')}</span><input id="capture-gallery" type="file" accept="image/*" hidden></label></div><div id="capture-preview-wrap"></div><div class="field"><label>${t('Save into','محفوظ کریں')}</label><select id="capture-cat">${Object.keys(cats).filter(k=>k!=='vault'&&k!=='reminders').map(k=>`<option value="${k}">${catLabel(k)}</option>`).join('')}</select></div><div class="field"><label>${t('Title','عنوان')}</label><input id="capture-title" placeholder="${t('What is this?','یہ کیا ہے؟')}"></div><div class="field"><label>${t('Note','نوٹ')}</label><textarea id="capture-note" placeholder="${t('Add details…','تفصیل لکھیں…')}"></textarea></div><div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button type="button" class="primary" id="capture-save">${t('Save capture','کیپچر محفوظ کریں')}</button></div></div>`);sh.querySelector('[data-close]').addEventListener('click',()=>sh.remove());let photo='';const useFile=async file=>{if(file){photo=await imageData(file);sh.querySelector('#capture-preview-wrap').innerHTML=`<img class="photo-preview" src="${photo}">`}};sh.querySelector('#capture-camera').addEventListener('change',e=>useFile(e.target.files[0]));sh.querySelector('#capture-gallery').addEventListener('change',e=>useFile(e.target.files[0]));sh.querySelector('#capture-save').addEventListener('click',async()=>{const title=sh.querySelector('#capture-title').value.trim()||t('Captured memory','محفوظ یاد');const category=sh.querySelector('#capture-cat').value;state.items.unshift({id:uid(),category,title,note:sh.querySelector('#capture-note').value,photo,date:today(),createdAt:nowISO(),updatedAt:nowISO()});touchStreak();await save();sh.remove();toast(t('Capture saved','کیپچر محفوظ ہوگیا'));render()})}
  async function profileSheet(){const sh=openSheet(`<div class="sheet-title"><h2>${t('Profile','پروفائل')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><form class="form" id="profile-form"><div style="text-align:center"><div class="brand-mark" style="width:86px;height:86px;margin:auto;overflow:hidden">${state.profile.photo?`<img id="profile-preview" src="${esc(state.profile.photo)}" style="width:100%;height:100%;object-fit:cover">`:I('user')}</div></div><label class="photo-picker">${I('camera')} ${t('Choose profile photo','پروفائل تصویر منتخب کریں')}<input id="profile-photo" type="file" accept="image/*" hidden></label>${field(t('Display name','نام'),'text','name',state.profile.name,'Muhammad Usman')}<div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Save profile','پروفائل محفوظ کریں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',()=>sh.remove()));let photo=state.profile.photo;sh.querySelector('#profile-photo').onchange=async e=>{if(e.target.files[0]){photo=await imageData(e.target.files[0],600);sh.querySelector('#profile-preview')?.setAttribute('src',photo)}};sh.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();state.profile={name:new FormData(e.target).get('name'),photo};await save();sh.remove();toast(t('Profile saved','پروفائل محفوظ ہوگیا'));render()}}
  async function vault(){if(!state.vault.data){return vaultSetup()}return vaultUnlock()}
  async function deriveKey(pass,salt){const enc=new TextEncoder();const base=await crypto.subtle.importKey('raw',enc.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:210000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
  function b64(buf){return btoa(String.fromCharCode(...new Uint8Array(buf)))}
  function unb64(s){const bin=atob(s);return Uint8Array.from(bin,c=>c.charCodeAt(0))}
  async function encryptVault(pass,obj,salt){const iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(pass,salt);const data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(obj)));return b64(iv)+'$'+b64(data)}
  async function decryptVault(pass,payload,salt){const [ivS,dataS]=payload.split('$');const key=await deriveKey(pass,salt);const data=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(ivS)},key,unb64(dataS));return JSON.parse(new TextDecoder().decode(data))}
  function vaultSetup(){const sh=openSheet(`<div class="sheet-title"><h2>${t('Secure Vault','محفوظ والٹ')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="vault-lock">${I('shield')} ${t('Vault data is encrypted locally with AES-GCM. Yaad Saathi cannot recover a forgotten passphrase. Save your recovery key in a safe place.','والٹ کا ڈیٹا مقامی طور پر AES-GCM سے encrypted ہے۔ بھولا ہوا passphrase Yaad Saathi واپس نہیں لا سکتا۔ recovery key محفوظ جگہ رکھیں۔')}</div><form class="form" id="vault-setup">${field(t('Create a passphrase','پاس فریز بنائیں'),'password','pass','','Use a strong phrase','required')}${field(t('Confirm passphrase','پاس فریز دوبارہ لکھیں'),'password','confirm','','Repeat it','required')}<div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Create secure vault','محفوظ والٹ بنائیں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>sh.remove());sh.querySelector('#vault-setup').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),p=fd.get('pass'),c=fd.get('confirm');if(p!==c||String(p).length<8){toast(t('Use the same passphrase with at least 8 characters.','ایک جیسا کم از کم 8 حروف کا پاس فریز رکھیں۔'));return}const salt=crypto.getRandomValues(new Uint8Array(16));state.vault={salt:b64(salt),data:await encryptVault(p,[],salt)};await save();sh.remove();toast(t('Secure Vault created','محفوظ والٹ بن گیا'));vaultUnlock()}}
  function vaultUnlock(){const sh=openSheet(`<div class="sheet-title"><h2>${t('Secure Vault','محفوظ والٹ')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="vault-lock">${I('lock')} ${t('Your vault is locked. Unlock it to view account details and passwords.','آپ کا والٹ لاک ہے۔ اکاؤنٹ کی تفصیل اور پاس ورڈ دیکھنے کے لیے unlock کریں۔')}</div><form class="form" id="vault-unlock">${field(t('Passphrase','پاس فریز'),'password','pass','','Enter your passphrase','required')}<div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Unlock','کھولیں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>sh.remove());sh.querySelector('#vault-unlock').onsubmit=async e=>{e.preventDefault();try{const p=new FormData(e.target).get('pass'),salt=unb64(state.vault.salt),items=await decryptVault(p,state.vault.data,salt);sh.remove();vaultEditor(items)}catch{toast(t('Wrong passphrase','غلط پاس فریز'))}}}
  function vaultEditor(items){
    const sh=openSheet(`<div class="sheet-title"><h2>${t('Secure Vault','محفوظ والٹ')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="vault-lock">${I('shield')} ${t('For account emails, passwords and private login details. Data is encrypted before storage.','ای میل، پاس ورڈ اور نجی لاگ اِن تفصیل کے لیے۔ محفوظ کرنے سے پہلے ڈیٹا encrypted ہوتا ہے۔')}</div><div class="list-grid" id="vault-list">${items.length?items.map((x,i)=>`<article class="record"><div class="thumb">${I('lock')}</div><div class="record-body"><div class="item-title">${esc(x.name)}</div><div class="item-meta">${esc(x.email||'')}</div><div class="item-meta" id="vp-${i}">••••••••</div></div><button class="small-btn" data-vshow="${i}">${I('eye')}</button><button class="small-btn danger" data-vdel="${i}">${I('trash')}</button></article>`).join(''):`<div class="empty"><div class="empty-icon">${I('lock')}</div><h3>${t('Vault is empty','والٹ خالی ہے')}</h3><p>${t('Add a login or private account detail.','نئی لاگ اِن یا نجی تفصیل شامل کریں۔')}</p></div>`}</div><div class="form-actions"><button class="secondary" id="vault-add">${I('plus')} ${t('Add secure item','محفوظ چیز شامل کریں')}</button><button class="primary" id="vault-save">${t('Save & lock','محفوظ کریں اور لاک کریں')}</button></div>`);
    sh.querySelector('[data-close]').onclick=()=>sh.remove();
    sh.querySelector('#vault-add').onclick=()=>{const name=prompt(t('Service name (e.g. Gmail)','سروس کا نام'));if(!name)return;const email=prompt(t('Email / username','ای میل / یوزرنیم'))||'';const pass=prompt(t('Password','پاس ورڈ'))||'';items.push({name,email,pass});sh.remove();vaultEditor(items)};
    sh.querySelector('#vault-save').onclick=async()=>{const p=prompt(t('Enter your vault passphrase to save changes:','تبدیلی محفوظ کرنے کے لیے پاس فریز لکھیں:'));if(!p)return;try{const salt=unb64(state.vault.salt);state.vault.data=await encryptVault(p,items,salt);await save();sh.remove();toast(t('Vault updated and locked','والٹ اپ ڈیٹ اور لاک ہوگیا'))}catch{toast(t('Could not save vault','والٹ محفوظ نہیں ہو سکا'))}};
    sh.querySelectorAll('[data-vshow]').forEach(btn=>btn.onclick=()=>{const i=+btn.dataset.vshow;const el=sh.querySelector('#vp-'+i);if(el)el.textContent=el.textContent==='••••••••'?items[i].pass:'••••••••'});
    sh.querySelectorAll('[data-vdel]').forEach(btn=>btn.onclick=async()=>{if(confirm(t('Delete this secure item?','یہ محفوظ چیز حذف کریں؟'))){items.splice(+btn.dataset.vdel,1);sh.remove();vaultEditor(items)}});
  }
  function manageCustomCategories(){const current=(state.customCats||[]);const sh=openSheet(`<div class="sheet-title"><h2>${t('Custom Categories','اپنی کیٹیگریز')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="vault-lock">${t('Create up to two categories for anything that does not fit the main sections. You can rename them later.','دو ذاتی کیٹیگریز بنائیں۔ بعد میں ان کے نام تبدیل بھی کر سکتے ہیں۔')}</div><form class="form" id="custom-form">${field(t('Category 1','کیٹیگری 1'),'text','c1',current[0]?.label||'','e.g. Home Projects')}${field(t('Category 2','کیٹیگری 2'),'text','c2',current[1]?.label||'','e.g. Travel')}<div class="form-actions"><button type="button" class="secondary" data-close>${t('Cancel','منسوخ')}</button><button class="primary">${t('Save categories','کیٹیگریز محفوظ کریں')}</button></div></form>`);sh.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>sh.remove());sh.querySelector('#custom-form').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);state.customCats=[String(fd.get('c1')||'').trim(),String(fd.get('c2')||'').trim()].filter(Boolean).slice(0,2).map(label=>({label}));syncCustomCats();await save();sh.remove();toast(t('Custom categories saved','اپنی کیٹیگریز محفوظ ہوگئیں'));render()}}
  function exportData(){const copy=JSON.parse(JSON.stringify(state));const blob=new Blob([JSON.stringify({version:3,exportedAt:nowISO(),data:copy},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='yaad-saathi-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast(t('Backup exported','بیک اپ ایکسپورٹ ہوگیا'))}
  function importData(){const input=document.createElement('input');input.type='file';input.accept='application/json';input.onchange=()=>{const f=input.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{const x=JSON.parse(r.result);state=x.data||x;normalize();await save();toast(t('Backup restored','بیک اپ واپس آگیا'));render()}catch{toast(t('Invalid backup file','غلط بیک اپ فائل'))}};r.readAsText(f)};input.click()}
  async function toggleNotifications(){if(!('Notification' in window)){toast(t('Notifications are not supported here.','اس براؤزر میں notifications سپورٹ نہیں ہیں۔'));return}const p=await Notification.requestPermission();state.notifications=p==='granted';await save();toast(state.notifications?t('Notifications enabled','اطلاعات فعال ہوگئیں'):t('Notifications not enabled','اطلاعات فعال نہیں ہوئیں'));render()}
  function scheduleReminders(){reminderTimers.forEach(clearTimeout);reminderTimers=[];if(!state.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const jobs=[];for(const r of state.reminders.filter(x=>!x.completed&&x.date&&x.time)){jobs.push({when:r.date+'T'+r.time,title:r.title,tag:r.id,body:r.note||t('Reminder time','یاد دہانی کا وقت')})}for(const x of state.items.filter(x=>x.category==='futureMe'&&!x.sent&&x.date&&x.time)){jobs.push({when:x.date+'T'+x.time,title:x.title,tag:x.id,body:x.note||t('A message from your past self','آپ کے ماضی کے آپ کا پیغام')})}for(const j of jobs){const ms=new Date(j.when)-new Date();if(ms>0&&ms<2147483647){reminderTimers.push(setTimeout(async()=>{new Notification(j.title,{body:j.body,icon:'./icon-192.png',tag:j.tag});const f=state.items.find(x=>x.id===j.tag);if(f){f.sent=true;await dbPut(state)}},ms))}}}
  function installFlow(){if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>{deferredInstall=null;hideInstall()});return}toast(t('Use your browser menu and choose Add to Home screen.','براؤزر مینو کھولیں اور Add to Home screen منتخب کریں۔'))}
  function showInstall(){const el=document.getElementById('install-banner');if(el&&!state.installDismissed&&!window.matchMedia('(display-mode: standalone)').matches){el.classList.remove('hidden');}}
  function hideInstall(){const el=document.getElementById('install-banner');el?.remove();}
  function shareApp(){if(navigator.share)navigator.share({title:'Yaad Saathi',text:'Yaad Saathi — یاد ساتھی',url:location.href}).catch(()=>{});else navigator.clipboard?.writeText(location.href).then(()=>toast(t('App link copied','ایپ لنک کاپی ہوگیا')))}
  function bindCommon(){if(!window.__yaadScrollBound){window.__yaadScrollBound=true;window.addEventListener('scroll',()=>{const h=document.querySelector('.topbar');if(h)h.classList.toggle('scrolled',window.scrollY>10)},{passive:true})}app.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{route=b.dataset.route;window.__query='';render()});app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{const k=b.dataset.category;route='cat:'+k;render()});app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});app.querySelectorAll('[data-theme]').forEach(b=>b.onclick=async()=>{state.theme=b.dataset.theme;await save();render()});app.querySelectorAll('[data-lang]').forEach(b=>b.onclick=async()=>{state.lang=b.dataset.lang;await save();render()});app.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action,id=b.dataset.id;if(a==='add')openAdd();if(a==='menu')openMenu();if(a==='search'){route='search';render()}if(a==='profile')profileSheet();if(a==='see-all'){route='all';render()}if(a==='capture-photo')openSmartCapture('photo');if(a==='capture-note')openSmartCapture('note');if(a==='open-record')openRecord(id);if(a==='edit-record'){const x=state.items.find(x=>x.id===id);if(x)openCategory(x.category,id)}if(a==='delete-record'){if(confirm(t('Delete this item?','یہ آئٹم حذف کریں؟'))){state.items=state.items.filter(x=>x.id!==id);await save();toast(t('Deleted','حذف ہوگیا'));render()}}if(a==='add-category')openCategory(b.dataset.category);if(a==='open-reminder')openReminder(id);if(a==='edit-reminder')openReminder(id);if(a==='delete-reminder'){if(confirm(t('Delete this reminder?','یہ یاد دہانی حذف کریں؟'))){state.reminders=state.reminders.filter(x=>x.id!==id);await save();render()}}if(a==='toggle-reminder'){const r=state.reminders.find(x=>x.id===id);if(r){r.completed=!r.completed;await save();render()}}if(a==='toggle-notifications')toggleNotifications();if(a==='install')installFlow();if(a==='dismiss-install'){state.installDismissed=true;await save();hideInstall()}if(a==='share')shareApp();if(a==='copy-link'){navigator.clipboard?.writeText(location.href).then(()=>toast(t('Link copied','لنک کاپی ہوگیا')))}if(a==='export')exportData();if(a==='import')importData();if(a==='clear-data'){if(confirm(t('Delete all local Yaad Saathi data? This cannot be undone.','تمام مقامی ڈیٹا حذف کرنا ہے؟ یہ واپس نہیں ہوگا۔'))){state=empty();await save();render();toast(t('All data cleared','تمام ڈیٹا صاف ہوگیا'))}}if(a==='custom-categories')manageCustomCategories();if(a==='privacy-info')openSheet(`<div class="sheet-title"><h2>${t('Privacy','پرائیویسی')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="vault-lock">${I('shield')} ${t('Yaad Saathi is designed to keep ordinary data on this device. Secure Vault uses Web Crypto AES-GCM encryption with a passphrase-derived key. No app can honestly promise absolute security on a compromised device, and a forgotten vault passphrase cannot be recovered by this app.','یاد ساتھی عام ڈیٹا اسی ڈیوائس پر رکھنے کے لیے بنایا گیا ہے۔ Secure Vault Web Crypto AES-GCM encryption استعمال کرتا ہے۔ کسی compromised device پر absolute security کی ضمانت ممکن نہیں، اور بھولا ہوا passphrase یہ app واپس نہیں لا سکتی۔')}</div>`);if(a==='new-notebook')openNotebook();if(a==='edit-notebook')openNotebook(id);if(a==='delete-notebook'){if(confirm(t('Delete this note?','یہ نوٹ حذف کریں؟'))){state.notebook=state.notebook.filter(x=>x.id!==id);await save();render()}}});}
  function bindSearch(){const input=document.getElementById('global-search');input?.addEventListener('input',()=>{window.__query=input.value;clearTimeout(window.__searchT);window.__searchT=setTimeout(render,120)})}
  function openRecord(id){const x=state.items.find(y=>y.id===id);if(!x)return;const sh=openSheet(`<div class="sheet-title"><h2>${esc(x.title)}</h2><button class="icon-btn" data-close>${I('x')}</button></div>${x.photo?`<img class="photo-preview" src="${esc(x.photo)}">`:''}<div class="vault-lock">${I(cats[x.category]?.icon||'spark')} ${catLabel(x.category)} · ${fmtDate(x.date||x.createdAt.slice(0,10))}</div>${x.note?`<p style="color:var(--muted);line-height:1.6">${esc(x.note)}</p>`:''}${x.audio?`<audio controls style="width:100%" src="${esc(x.audio)}"></audio>`:''}<div class="form-actions"><button class="secondary" data-close>${t('Close','بند')}</button><button class="primary" data-edit>${t('Edit','ترمیم')}</button></div>`);sh.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>sh.remove());sh.querySelector('[data-edit]').onclick=()=>{sh.remove();openCategory(x.category,x.id)}}
  function openAdd(){openSheet(`<div class="sheet-title"><h2>${t('What would you like to save?','آپ کیا محفوظ کرنا چاہتے ہیں؟')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="category-grid">${Object.keys(cats).map(k=>`<button class="category-btn" data-addcat="${k}"><div class="qicon">${I(cats[k].icon)}</div><strong>${catLabel(k)}</strong><span>${esc(cats[k].hint)}</span></button>`).join('')}</div>`).querySelectorAll('[data-addcat]').forEach(b=>b.onclick=()=>{const k=b.dataset.addcat;if(k==='vault'){document.querySelector('.modal-backdrop')?.remove();vault()}else if(k==='reminders'){document.querySelector('.modal-backdrop')?.remove();openReminder()}else{document.querySelector('.modal-backdrop')?.remove();openCategory(k)}})}
  function openMenu(){openSheet(`<div class="sheet-title"><h2>${t('Yaad Saathi','یاد ساتھی')}</h2><button class="icon-btn" data-close>${I('x')}</button></div><div class="list-grid"><button class="setting-row glass" data-menu="notebook"><div class="row-icon">${I('notebook')}</div><div class="setting-copy"><strong>${t('My Notebook','میری نوٹ بک')}</strong><span>${t('A separate space for longer notes.','تفصیلی نوٹس کے لیے الگ جگہ۔')}</span></div>${I('chev')}</button><button class="setting-row glass" data-menu="vault"><div class="row-icon">${I('lock')}</div><div class="setting-copy"><strong>${t('Secure Vault','محفوظ والٹ')}</strong><span>${t('Encrypted account details and passwords.','encrypted اکاؤنٹ تفصیل اور پاس ورڈ۔')}</span></div>${I('chev')}</button><button class="setting-row glass" data-menu="all"><div class="row-icon">${I('archive')}</div><div class="setting-copy"><strong>${t('All categories','تمام کیٹیگریز')}</strong><span>${t('Browse everything in one place.','سب کچھ ایک جگہ دیکھیں۔')}</span></div>${I('chev')}</button></div>`);document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=()=>{document.querySelector('.modal-backdrop')?.remove();route=b.dataset.menu==='notebook'?'notebook':b.dataset.menu==='all'?'all':'cat:vault';if(route==='cat:vault')vault();else render()})}
  document.addEventListener('click',e=>{const b=e.target.closest?.('[data-action=install],[data-action=dismiss-install]');if(!b)return;if(b.dataset.action==='install')installFlow();if(b.dataset.action==='dismiss-install'){state.installDismissed=true;save();hideInstall()}});
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;clearTimeout(installTimer);installTimer=setTimeout(showInstall,5000)});
  window.addEventListener('appinstalled',()=>{deferredInstall=null;hideInstall()});
  window.addEventListener('load',async()=>{state=await dbGet()||JSON.parse(localStorage.getItem(DB)||'null')||empty();normalize();touchStreak();await save();render();setTimeout(()=>{if(!state.installDismissed&&deferredInstall)showInstall()},5000);scheduleReminders()});
})();
